-- 工艺归并：旧编号成为别名（processes.merged_into_id），历史样本分批迁移（process_merges）。
-- Bootstrap schema is also generated by SQLAlchemy Base.metadata.create_all.
ALTER TABLE processes ADD COLUMN IF NOT EXISTS merged_into_id INTEGER REFERENCES processes(id);
CREATE TABLE IF NOT EXISTS process_merges(
    id SERIAL PRIMARY KEY,
    source_id INTEGER NOT NULL REFERENCES processes(id),
    target_id INTEGER NOT NULL REFERENCES processes(id),
    status VARCHAR(20) NOT NULL,
    expected_total INTEGER NOT NULL,
    moved INTEGER NOT NULL,
    batch_size INTEGER NOT NULL,
    actor VARCHAR(120) NOT NULL,
    error TEXT NOT NULL,
    created_at VARCHAR(40) NOT NULL,
    updated_at VARCHAR(40) NOT NULL,
    finished_at VARCHAR(40) NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_process_merges_status ON process_merges(status);
CREATE INDEX IF NOT EXISTS ix_samples_process ON samples(process_id);
